<?php $title='Login';require '../includes/header.php';if(logged()) redirect('../index.php');if($_SERVER['REQUEST_METHOD']==='POST'){ $s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([trim($_POST['email'])]);$u=$s->fetch();if($u && password_verify($_POST['password'],$u['password'])){$_SESSION['user']=$u;flash('Welcome back, '. $u['name'].'!');redirect('../index.php');}flash('Invalid email or password.','error');} ?><section class="auth"><div class="authbox"><span class="eyebrow">WELCOME BACK</span><h1>Sign in</h1><p>Access your cart, orders and account.</p><form method="post"><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary full">Login</button></form><p>New customer? <a href="register.php">Create an account</a></p><div class="demo">Demo admin: admin@shopnest.test / password</div></div></section><?php require '../includes/footer.php'; ?>